; Duck Hunt -- the ROM bank: the NES RAM ($0000-$07FF), the support area below $C000 and the 16KB
; PRG-ROM at $C000-$FFFF, at its NES addresses (rom_code.s, generated by tools/convert.js).  The
; cartridge is NROM-128: the PRG-ROM is mirrored at $8000-$BFFF on the NES, but the code never uses the
; mirror, so the support area is there.

            mx    %11

            put   ram.s                       ; The RAM map (generated)

HORIZONTAL_MIRRORING equ $01                  ; From core/Defs.s, which is not put in the ROM segment
VERTICAL_MIRRORING   equ $02

ROMBase     ENT
            ds    $0800                       ; The NES RAM ($0000-$07FF; the zero page and the stack are
                                              ; the NES task's direct page and stack, in bank 0)

            ds    $B000-*

y_exclude   ENT                               ; Table of excluded sprite Y values -- filled in by InitYExclude at start-up
            ds    256

tile_exclude ENT                              ; Table of excluded tiles (none)
            ds    256

            put   Config.s                    ; HAS_CHR_RAM and the other engine constants rom_inject.s tests
            put   ../../ppu/ppu_reg_vars.s    ; PPU state, only put in the base ROM bank
            put   ../../rom/rom_inject.s      ; The PPU / APU register hooks
            put   abs_y.s                     ; The abs,Y and jmp (ind) helpers (generated)
            put   support.s                   ; The routines the patches call

            ds    $C000-*
            put   rom_code.s                  ; $C000-$FFFF (generated)
